}

.notification.success {
  background: #10b981;
  color: white;
}

.notification.error {
  background: #ef4444;
  color: white;
}

.notification.warning {
  background: #f59e0b;
  color: white;
}

.notification.info {
  background: #3b82f6;
  color: white;
}

.notification button {
  background: none;
  border: none;
  color: white;
  cursor: pointer;
  font-size: 16px;
}

