.task-form {
  padding: 20px;
}

.form-group {
  margin-bottom: 16px;
}

.form-group label {
  display: block;
  margin-bottom: 8px;
  font-weight: 500;
  font-size: 14px;
}

.form-group input,
.form-group textarea,
.form-group select {
  width: 100%;
  padding: 8px 12px;
  border: 1px solid #e2e8f0;
  border-radius: 8px;
  font-size: 14px;
}

.dark-theme .form-group input,
.dark-theme .form-group textarea,
.dark-theme .form-group select {
  background: #1e293b;
  border-color: #334155;
  color: #e0e0e0;
}

.form-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
}

.tag-selector {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}

.selectable-tag {
  padding: 4px 12px;
  background: #f1f5f9;
  border-radius: 20px;
